insert into public.question_keys (question_id, answer, explanation, wrong, mistakes) values
  ('preu-math-001', '{"value":4,"tolerance":0}'::jsonb, 'Factorise: (x² − 4)/(x − 2) = (x + 2)(x − 2)/(x − 2) = x + 2 for x ≠ 2. As x → 2, this approaches 4.', null, '[{"value":0,"why":"Substituting directly gives 0/0, which is undefined, not 0. Factorise first."}]'::jsonb),
  ('preu-math-002', '"a"'::jsonb, 'd/dx (sin x) = cos x. The slope of the sine curve at any point equals the value of cosine there.', '{"b":"−cos x is the integral of sin x (plus c), not its derivative.","c":"−sin x is the derivative of cos x.","d":"tan x is sin x / cos x, not a derivative of sin x."}'::jsonb, null),
  ('preu-math-003', '{"value":8,"tolerance":0}'::jsonb, '∫ 3x² dx = x³. Evaluate from 0 to 2: 2³ − 0³ = 8.', null, '[{"value":12,"why":"12 is the derivative 6x at x = 2; integrate instead."},{"value":24,"why":"Divide by the new power: 3x³/3 = x³, not 3x³."}]'::jsonb),
  ('preu-math-004', '"a"'::jsonb, 'By the chain rule, d/dx e^(u) = e^(u) · du/dx. With u = 2x, du/dx = 2, so the derivative is 2e^(2x).', '{"b":"Multiply by the derivative of the inner function 2x, which is 2.","c":"The power rule does not apply to exponentials; e^(u) differentiates to itself times u′.","d":"Dividing by 2 is what integration does."}'::jsonb, null),
  ('preu-math-005', '{"value":5,"tolerance":0}'::jsonb, '|a + bi| = √(a² + b²) = √(9 + 16) = √25 = 5.', null, '[{"value":7,"why":"7 adds the parts; the modulus is √(3² + 4²)."},{"value":25,"why":"25 is |z|²; take the square root."}]'::jsonb),
  ('preu-math-006', '{"value":5,"tolerance":0}'::jsonb, 'For a 2 × 2 matrix with rows (a, b) and (c, d), the determinant is ad − bc = 2 × 4 − 3 × 1 = 5.', null, '[{"value":11,"why":"11 is ad + bc; subtract bc instead."},{"value":-5,"why":"Order matters: ad − bc, not bc − ad."}]'::jsonb),
  ('preu-math-007', '"a"'::jsonb, 'a = 8 and r = 1/2. Since |r| < 1, S∞ = a/(1 − r) = 8/(1/2) = 16.', '{"b":"15 is the sum of only the first four terms.","c":"8 is just the first term.","d":"A geometric series converges when |r| < 1, and here r = 1/2."}'::jsonb, null),
  ('preu-math-008', '"true"'::jsonb, 'x³ is strictly increasing, so different inputs always give different outputs. Any horizontal line meets its graph exactly once.', '{"false":"Unlike x², the function x³ never repeats a value: (−2)³ = −8 but 2³ = 8. It passes the horizontal line test."}'::jsonb, null),
  ('preu-math-009', '{"value":3,"tolerance":0}'::jsonb, 'ln is the inverse of eˣ, so ln(e³) = 3.', null, '[{"value":20.09,"why":"20.09 is e³ itself; the natural log undoes the exponential."}]'::jsonb),
  ('preu-math-010', '["a","b","e"]'::jsonb, '(−x)² = x², cos(−x) = cos x and |−x| = |x|. Their graphs are symmetric about the y-axis.', '{"c":"(−x)³ = −x³, so x³ is odd.","d":"sin(−x) = −sin x, so sin x is odd."}'::jsonb, null),
  ('preu-math-011', '["c","a","d","b"]'::jsonb, 'Base case (n = 1), inductive hypothesis (assume n = k), inductive step (prove n = k + 1), then the conclusion.', null, null),
  ('preu-math-012', '{"value":10,"tolerance":0}'::jsonb, 'The x² term is ⁵C₂ × x² = 10x², so the coefficient is 10.', null, '[{"value":5,"why":"5 is the coefficient of x (⁵C₁); for x² use ⁵C₂."},{"value":25,"why":"25 is 5²; use the binomial coefficient ⁵C₂ = 10."}]'::jsonb),
  ('preu-phy-001', '{"value":16,"tolerance":0,"unit":"J"}'::jsonb, 'KE = ½mv² = ½ × 2 × 4² = 16 J.', null, '[{"value":8,"why":"8 is mv (momentum); kinetic energy uses ½mv²."},{"value":32,"why":"Remember the ½: ½ × 2 × 16 = 16."}]'::jsonb),
  ('preu-phy-002', '{"value":490.5,"tolerance":0.5,"unit":"J"}'::jsonb, 'ΔGPE = mgh = 5 × 9.81 × 10 = 490.5 J.', null, '[{"value":50,"why":"Multiply by g as well: mgh, not just mh."}]'::jsonb),
  ('preu-phy-003', '"a"'::jsonb, 'Each half-life halves what is left: 1 → 1/2 → 1/4 → 1/8.', '{"b":"Decay halves the sample each time; it does not divide by the number of half-lives.","c":"1/6 is 1/(2 × 3); halving three times is 1/2³.","d":"1/9 is 1/3², not (1/2)³."}'::jsonb, null),
  ('preu-phy-004', '{"value":2,"tolerance":0,"unit":"Ω"}'::jsonb, '1/R = 1/6 + 1/3 = 1/6 + 2/6 = 3/6 = 1/2, so R = 2 Ω. A parallel combination is always less than the smallest resistor.', null, '[{"value":9,"why":"9 Ω is the series total; for parallel, add the reciprocals."},{"value":0.5,"why":"0.5 is 1/R; take the reciprocal to get R."}]'::jsonb),
  ('preu-phy-005', '"a"'::jsonb, 'Each photon has energy hf. Higher frequency means more energy per photon, so KEmax = hf − φ increases.', '{"b":"Brighter light sends more photons, so more electrons are emitted, but each photon has the same energy.","c":"Plate size changes how many electrons can be emitted, not their maximum energy.","d":"Each electron absorbs one photon; waiting longer does not add energy to it."}'::jsonb, null),
  ('preu-phy-006', '"false"'::jsonb, 'In SHM, a = −ω²x. Acceleration is proportional to displacement, so it is zero at equilibrium and greatest at the extremes (x = ±A). It is the speed that is greatest at equilibrium.', '{"true":"That describes speed, not acceleration. At equilibrium x = 0, so a = −ω²x = 0."}'::jsonb, null),
  ('preu-phy-007', '{"value":4,"tolerance":0,"unit":"N"}'::jsonb, 'F = mv²/r = 0.5 × 4² / 2 = 0.5 × 16 / 2 = 4 N.', null, '[{"value":1,"why":"Square the speed: v² = 16, not 4."},{"value":16,"why":"Divide by the radius: mv²/r."}]'::jsonb),
  ('preu-phy-008', '{"a":"y","b":"z","c":"x"}'::jsonb, 'Protons are positive (+1), electrons negative (−1) and neutrons neutral (0).', null, null),
  ('preu-phy-009', '["a","b"]'::jsonb, 'Momentum is conserved in every collision without external forces. In an elastic collision, total kinetic energy is conserved too.', '{"c":"Individual speeds usually change; only the totals are conserved.","d":"Objects often bounce off in new directions."}'::jsonb, null),
  ('preu-phy-010', '{"value":2,"tolerance":0.01,"unit":"× 10⁸ m/s"}'::jsonb, 'n = c/v, so v = c/n = 3.0 × 10⁸ / 1.5 = 2.0 × 10⁸ m/s.', null, '[{"value":4.5,"why":"4.5 multiplies by n; light slows down in glass, so divide by n."}]'::jsonb),
  ('preu-chem-001', '"a"'::jsonb, 'Four bonding pairs around carbon repel each other equally, giving a tetrahedral shape with 109.5° bond angles.', '{"b":"Trigonal planar has three electron pairs, as in BF₃.","c":"Linear has two electron pairs, as in CO₂.","d":"Octahedral has six electron pairs, as in SF₆."}'::jsonb, null),
  ('preu-chem-002', '{"value":2,"tolerance":0.01}'::jsonb, 'HCl fully ionises, so [H⁺] = 0.01 = 10⁻² mol/dm³. pH = −log₁₀[H⁺] = 2.', null, '[{"value":0.01,"why":"0.01 is the hydrogen ion concentration; pH = −log₁₀ of it."},{"value":-2,"why":"pH has a minus sign in front of the log: −log(10⁻²) = 2."}]'::jsonb),
  ('preu-chem-003', '"a"'::jsonb, 'There are 4 moles of gas on the left and 2 on the right. Higher pressure favours the side with fewer gas moles, so more NH₃ forms.', '{"b":"The left side has more gas moles; raising pressure favours fewer moles.","c":"Pressure affects equilibria whenever the gas moles differ on each side.","d":"An equilibrium is dynamic; changing pressure shifts it but does not stop it."}'::jsonb, null),
  ('preu-chem-004', '{"value":7,"tolerance":0}'::jsonb, 'K is +1 and each O is −2. The compound is neutral: +1 + Mn + 4(−2) = 0, so Mn = +7.', null, '[{"value":8,"why":"Include potassium''s +1: 1 + Mn − 8 = 0 gives Mn = +7."}]'::jsonb),
  ('preu-chem-005', '["a","c","e"]'::jsonb, 'Alkanes have the general formula CₙH₂ₙ₊₂: CH₄ (n = 1), C₃H₈ (n = 3) and C₄H₁₀ (n = 4).', '{"b":"C₂H₄ (ethene) fits CₙH₂ₙ: it is an alkene.","d":"C₂H₂ (ethyne) fits CₙH₂ₙ₋₂: it is an alkyne."}'::jsonb, null),
  ('preu-chem-006', '"a"'::jsonb, 'A catalyst offers an alternative route with lower activation energy, so more collisions have enough energy to react.', '{"b":"A catalyst speeds up forward and reverse reactions equally, so the equilibrium position does not change.","c":"The enthalpy change ΔH is the same with or without a catalyst.","d":"A catalyst is regenerated at the end and not used up."}'::jsonb, null),
  ('preu-chem-007', '["b","d","a","c"]'::jsonb, 'Longer chains have more electrons and more surface contact, so stronger van der Waals forces and higher boiling points: methane < ethane < propane < butane.', null, null),
  ('preu-chem-008', '"true"'::jsonb, 'Benzene''s π electrons are delocalised around the ring, so all six C–C bonds are identical, between a single and a double bond in length.', '{"false":"The alternating single/double (Kekulé) picture is not accurate; delocalisation makes all six bonds equal."}'::jsonb, null),
  ('preu-chem-009', '{"accept":["hydrogenation","addition","addition reaction","catalytic hydrogenation"]}'::jsonb, 'Hydrogen adds across the C=C double bond: this is hydrogenation, a type of addition reaction. It is used to make margarine from vegetable oils.', null, null),
  ('preu-chem-010', '{"a":"y","b":"z","c":"x"}'::jsonb, 'C=C is the alkene group, −COOH the carboxylic acid group, and −COO− linking two chains is the ester group.', null, null),
  ('preu-bio-001', '"a"'::jsonb, 'The Krebs cycle happens in the matrix of the mitochondrion.', '{"b":"Glycolysis happens in the cytoplasm.","c":"The electron transport chain is on the inner membrane.","d":"The stroma is where the Calvin cycle of photosynthesis happens."}'::jsonb, null),
  ('preu-bio-002', '{"value":2,"tolerance":0}'::jsonb, 'Glycolysis uses 2 ATP and makes 4 ATP, a net gain of 2 ATP per glucose.', null, '[{"value":4,"why":"4 is the gross yield; 2 ATP are used at the start, so the net gain is 2."}]'::jsonb),
  ('preu-bio-003', '"a"'::jsonb, 'In DNA, adenine pairs with thymine (two hydrogen bonds) and guanine pairs with cytosine (three).', '{"b":"Uracil replaces thymine in RNA, not DNA.","c":"Guanine pairs with cytosine.","d":"Cytosine pairs with guanine."}'::jsonb, null),
  ('preu-bio-004', '{"value":0.48,"tolerance":0.005}'::jsonb, 'q² = 0.16, so q = 0.4 and p = 1 − 0.4 = 0.6. Heterozygote frequency = 2pq = 2 × 0.6 × 0.4 = 0.48.', null, '[{"value":0.24,"why":"0.24 is pq; heterozygotes are 2pq."},{"value":0.36,"why":"0.36 is p², the homozygous dominant frequency."}]'::jsonb),
  ('preu-bio-005', '["b","d","a","c"]'::jsonb, 'Prophase (chromosomes condense), metaphase (line up at the equator), anaphase (chromatids pulled apart), telophase (new nuclei form). Remember PMAT.', null, null),
  ('preu-bio-006', '["a","b","c"]'::jsonb, 'Light energy splits water, releasing oxygen, and produces ATP and reduced NADP for the Calvin cycle.', '{"d":"Glucose is made later, from the Calvin cycle (light-independent reactions).","e":"Carbon dioxide is used in the Calvin cycle, not produced by the light-dependent reactions."}'::jsonb, null),
  ('preu-bio-007', '"false"'::jsonb, 'mRNA is made from DNA during transcription, in the nucleus. Translation happens at ribosomes, where mRNA is read to build a polypeptide.', '{"true":"Making mRNA from DNA is transcription; translation is using mRNA to make a protein."}'::jsonb, null),
  ('preu-bio-008', '{"a":"y","b":"z","c":"x"}'::jsonb, 'Proteins are chains of amino acids, nucleic acids are chains of nucleotides, and starch is a chain of (α-)glucose.', null, null),
  ('preu-econ-001', '"a"'::jsonb, 'Price and quantity demanded move in opposite directions: a movement up along the demand curve.', '{"b":"That would contradict the law of demand for normal goods.","c":"A change in the good''s own price moves along the curve; it does not shift it.","d":"The law of demand is about buyers, not sellers."}'::jsonb, null),
  ('preu-econ-002', '{"value":20,"tolerance":0,"unit":"%"}'::jsonb, 'PED = %Δ quantity ÷ %Δ price, so %Δ quantity = −2 × 10% = −20%. Quantity demanded falls by 20%.', null, '[{"value":5,"why":"5 is 10 ÷ 2; multiply the price change by the elasticity."}]'::jsonb),
  ('preu-econ-003', '"a"'::jsonb, 'Choosing one thing means giving up the next best option. That forgone option is the opportunity cost.', '{"b":"The money price is only part of the picture; opportunity cost is about the alternative given up.","c":"Only the next best alternative counts, not all of them.","d":"That is marginal cost."}'::jsonb, null),
  ('preu-econ-004', '["a","b","c","e"]'::jsonb, 'The four factors of production are land, labour, capital (man-made tools and machinery) and entrepreneurship.', '{"d":"Money is a medium of exchange, not a factor of production; in economics, \"capital\" means physical goods used to produce other goods."}'::jsonb, null),
  ('preu-econ-005', '"true"'::jsonb, 'At the lower price, consumers want to buy more and producers supply less, so quantity demanded exceeds quantity supplied: a shortage.', '{"false":"Below equilibrium, demand is higher and supply lower than at equilibrium, which is exactly a shortage. (A ceiling above equilibrium would have no effect.)"}'::jsonb, null),
  ('preu-econ-006', '{"value":830,"tolerance":0}'::jsonb, 'GDP = C + I + G + (X − M) = 500 + 200 + 150 + (100 − 120) = 830.', null, '[{"value":1070,"why":"Imports are subtracted, not added: use (X − M)."},{"value":950,"why":"Imports were left out: subtract them too, 950 − 120 = 830."}]'::jsonb),
  ('preu-econ-007', '"a"'::jsonb, 'Demand-pull inflation happens when aggregate demand grows faster than the economy''s ability to produce, pulling prices up.', '{"b":"Higher oil prices raise production costs: that is cost-push inflation.","c":"Higher interest rates reduce spending and usually lower inflation.","d":"Falling wages lower costs and spending, which reduces inflation pressure."}'::jsonb, null),
  ('preu-econ-008', '{"a":"y","b":"z","c":"x"}'::jsonb, 'Perfect competition: many firms, identical goods. Monopoly: one seller. Oligopoly: a few big firms that react to each other''s decisions.', null, null),
  ('preu-econ-009', '"a"'::jsonb, 'Higher interest rates make borrowing dearer and saving more attractive, reducing spending and easing inflation.', '{"b":"Government spending is fiscal policy, decided by the government, not the central bank.","c":"Higher rates discourage borrowing.","d":"Higher rates usually strengthen the currency by attracting foreign savings."}'::jsonb, null),
  ('preu-econ-010', '{"accept":["gross domestic product","GDP"]}'::jsonb, 'Gross domestic product (GDP) measures the value of everything produced within a country''s borders in a period.', null, null)
